#include <Arduino.h>
#include <esp_ota_ops.h>
void setup() {
    const esp_partition_t* running = esp_ota_get_running_partition();
    esp_ota_img_states_t state;
    if (esp_ota_get_state_partition(running, &state) == ESP_OK && state == ESP_OTA_IMG_PENDING_VERIFY) {
        esp_ota_mark_app_valid_cancel_rollback();
    }
}
void loop() { delay(1000); }

#include <Arduino.h>
#include <esp_ota_ops.h>
void setup() { Serial.begin(115200); const esp_partition_t* part = esp_ota_get_running_partition(); if (part == nullptr) { Serial.println("running partition unavailable"); return; } esp_ota_img_states_t state; const esp_err_t result = esp_ota_get_state_partition(part, &state); if (result == ESP_OK) Serial.println(static_cast<int>(state)); else Serial.printf("partition state query failed: %d\n", static_cast<int>(result)); }
void loop() { delay(1000); }
